input.new_string:
# Custom exfil detection rule
# Alerts on HTTP POST to /telemetry/v2/report with X-TLM-Mode: exfil header
# and body containing Base64 blob (>=80 chars) and exactly 64 hex sig value
alert http any any -> any any (
  msg:"Custom telemetry exfil detected";
  flow:established,to_server;
  http.method;
  content:"POST";
  http.uri;
  content:"/telemetry/v2/report";
  http.header;
  content:"X-TLM-Mode|3a| exfil";
  http_client_body;
  content:"blob=";
  http_client_body;
  pcre:"/blob=[A-Za-z0-9+\\/]{80,}/";
  http_client_body;
  content:"sig=";
  http_client_body;
  pcre:"/sig=[0-9a-fA-F]{64}(?:&|$)/";
  sid:1000001;
  rev:1;
)

